  state: State = 'start';
  completedSteps = 0;
  validate(action: Action): Check {
    const expected: Record<Exclude<State, 'complete'>, Action['type']> = { start: 'inspect', inspected: 'wetHands', wet: 'applyCleanser', soaped: 'scrub', scrubbed: 'rinse', rinsed: 'dry', dried: 'closeTapWithTowel' };
