    }
    return { ok: true, message: 'Step accepted.' };
  }
  dispatch(action: Action): Check {
    const check = this.validate(action);
    if (!check.ok) return check;
    this.state = transitions[this.state];
    this.completedSteps += 1;
    return { ok: true, message: this.state === 'complete' ? 'Scenario complete.' : `Advanced to ${this.state}.` };
  }
  isComplete(): boolean { return this.state === 'complete' && this.completedSteps === 7; }
}
